    (v_test, 2, $q$NON_VERBAL$q$, NULL, 7, $q$Odd one out$q$, $q$Shading$q$, $q$odd one out$q$, $q$Which figure is the odd one out?$q$, $q$none$q$, NULL, $q$svg$q$, $q$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 80 80" width="80" height="80"><circle cx="18" cy="40" r="9" fill="#ffffff" stroke="#1f2937" stroke-width="2"/><polygon points="40.0,31.0 47.8,44.5 32.2,44.5" fill="#1f2937" stroke="#1f2937" stroke-width="2"/><polygon points="68.4,33.6 68.4,46.4 55.6,46.4 55.6,33.6" fill="#ffffff" stroke="#1f2937" stroke-width="2"/></svg>$q$, $q$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 80 80" width="80" height="80"><polygon points="18.0,31.0 25.8,44.5 10.2,44.5" fill="#ffffff" stroke="#1f2937" stroke-width="2"/><circle cx="40" cy="40" r="9" fill="#1f2937" stroke="#1f2937" stroke-width="2"/><polygon points="68.4,33.6 68.4,46.4 55.6,46.4 55.6,33.6" fill="#ffffff" stroke="#1f2937" stroke-width="2"/></svg>$q$, $q$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 80 80" width="80" height="80"><circle cx="18" cy="40" r="9" fill="#1f2937" stroke="#1f2937" stroke-width="2"/><polygon points="46.4,33.6 46.4,46.4 33.6,46.4 33.6,33.6" fill="#ffffff" stroke="#1f2937" stroke-width="2"/><polygon points="62.0,31.0 69.8,44.5 54.2,44.5" fill="#ffffff" stroke="#1f2937" stroke-width="2"/></svg>$q$, $q$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 80 80" width="80" height="80"><polygon points="24.4,33.6 24.4,46.4 11.6,46.4 11.6,33.6" fill="#1f2937" stroke="#1f2937" stroke-width="2"/><polygon points="40.0,31.0 47.8,44.5 32.2,44.5" fill="#ffffff" stroke="#1f2937" stroke-width="2"/><circle cx="62" cy="40" r="9" fill="#1f2937" stroke="#1f2937" stroke-width="2"/></svg>$q$, $q$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 80 80" width="80" height="80"><polygon points="24.4,33.6 24.4,46.4 11.6,46.4 11.6,33.6" fill="#ffffff" stroke="#1f2937" stroke-width="2"/><circle cx="40" cy="40" r="9" fill="#ffffff" stroke="#1f2937" stroke-width="2"/><polygon points="62.0,31.0 69